import "./components/dropDownSismos.css";

const SismosList = ({ 
  sismos, 
  sismoSeleccionado, 
  setSismoSeleccionado, 
  handleSismoClick,
  onIncrementarPagina, // Nueva prop
  cantPagina // Opcional, para mostrar el valor actual
}) => {

  const handleSelection = (sismo) => {
    if (!sismo) {
        setSismoSeleccionado(null);
    } else {
      console.log("Sismo seleccionado:", sismo);
      const sismoId = sismo.id.toString();
      setSismoSeleccionado(sismoId);
      handleSismoClick(sismo);
    }
  };

  const handleNextPage = () => {
    // Limpiar selección actual (opcional)
    setSismoSeleccionado(null);
    // Incrementar página
    onIncrementarPagina();
  };

  return (
    <div className="sismos-list-container">
      <h4 className="sismos-list-title">
        Sismos Recientes 
        {cantPagina && <span className="page-info">(Mostrando {cantPagina})</span>}
      </h4>
      
      {/* Botón para siguiente página */}
      <div 
        className="sismo-item next-page-item"
        onClick={handleNextPage}
        role="button"
        tabIndex={0}
      >
        <span className="sismo-clear">🗂️ Siguiente página (+5 más)</span>
        <span className="next-icon">→</span>
      </div>

      {/* Lista de sismos siempre visible */}
      <div className="sismos-list">
        {sismos.map((sismo) => (
          <div
            key={sismo.id}
            className={`sismo-item ${
              sismoSeleccionado === sismo.id.toString() ? 'active' : ''
            }`}
            onClick={() => handleSelection(sismo)}
            role="button"
            tabIndex={0}
          >
            <div className="sismo-info">
              <div className="sismo-location">
                <strong>{sismo.referenciaLocalizacion}</strong>
              </div>
              <div className="sismo-details">
                <span className="sismo-magnitude">
                  📊 Magnitud: {sismo.magnitud}
                </span>
                {sismo.fechaHora && (
                  <span className="sismo-date">
                    🕒 {new Date(sismo.fechaHora).toLocaleDateString()}
                  </span>
                )}
              </div>
            </div>
            {sismoSeleccionado === sismo.id.toString() && (
              <span className="selected-icon">✓</span>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default SismosList;
